	}

	const setTopK = (event: Event) => {
		const input = event.currentTarget as HTMLInputElement;
		const rawValue = input.value;
		const value = Number(rawValue);

		if (!/^\d+$/.test(rawValue) || value < 0 || value > 1000) {
			input.value = `${params.top_k ?? ''}`;
			return;
		}

		params.top_k = value;
	};
